"""HTML -> main text extraction with Chinese-charset safety, plus sentence utils."""
import re

from bs4 import BeautifulSoup

SPECIAL_SELECTORS = [
    ("mp.weixin.qq.com", "#js_content"),
    ("zhuanlan.zhihu.com", ".Post-RichTextContainer"),
    ("www.zhihu.com", ".RichContent-inner"),
    ("blog.csdn.net", "#content_views"),
    ("juejin.cn", "article"),
    ("icourse.club", "#main"),
]


def dammit(data):
    """bytes -> unicode with charset detection (handles GBK/GB2312 edu sites)."""
    if isinstance(data, str):
        return data
    ud = BeautifulSoup(data, "lxml")
    return ud.get_text() if False else ud.decode() if False else _dammit(data)


def _dammit(data):
    from bs4 import UnicodeDammit
    return UnicodeDammit(data, ["utf-8", "gb18030"]).unicode_markup or ""


def extract_main_text(html_bytes, url=""):
    """Return (text, method). trafilatura first, domain-specific container, then bs4."""
    html = _dammit(html_bytes) if isinstance(html_bytes, bytes) else html_bytes
    if not html or not html.strip():
        return "", "empty"
    try:
        import trafilatura
        t = trafilatura.extract(html, url=url or None, include_comments=False,
                                include_tables=True, favor_recall=True,
                                no_fallback=False)
        if t and len(t.strip()) > 120:
            return t.strip(), "trafilatura"
    except Exception:
        pass
    # domain-specific containers
    for frag, sel in SPECIAL_SELECTORS:
        if frag in url:
            soup = BeautifulSoup(html, "lxml")
            node = soup.select_one(sel)
            if node:
                txt = _soup_text(node)
                if len(txt) > 80:
                    return txt, f"css:{sel}"
            break
    soup = BeautifulSoup(html, "lxml")
    for tag in soup(["script", "style", "nav", "header", "footer", "aside",
                     "form", "noscript", "iframe", "button"]):
        tag.decompose()
    txt = _soup_text(soup.body or soup)
    return txt, "bs4"


def _soup_text(node):
    lines = []
    for el in node.stripped_strings:
        lines.append(el)
    return "\n".join(lines)


_SENT_SPLIT = re.compile(r"(?<=[。！？!?；;\n])")


def split_sentences(text):
    sents = []
    for chunk in _SENT_SPLIT.split(text or ""):
        s = chunk.strip()
        if s:
            sents.append(s)
    return sents


def clean_ws(text):
    return re.sub(r"[ \t\u3000]+", " ", (text or "").replace("\r", "")).strip()


def truncate_chars(s, n):
    s = (s or "").strip()
    return s if len(s) <= n else s[: n - 1] + "…"

