"""JSONL append helpers with light dedup ledgers."""
import hashlib
import json
import time
from pathlib import Path


def now_iso():
    return time.strftime("%Y-%m-%dT%H:%M:%S+08:00")


def sha1(s):
    return hashlib.sha1(s.encode("utf-8", "ignore")).hexdigest()


def append_jsonl(path, record):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(record, ensure_ascii=False) + "\n")


def load_jsonl(path):
    path = Path(path)
    out = []
    if not path.exists():
        return out
    with path.open(encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                out.append(json.loads(line))
            except Exception:
                continue
    return out


def load_key_set(path, key="url"):
    return {r.get(key) for r in load_jsonl(path) if r.get(key)}


def record_crawled(url, final_url="", status=200, note=""):
    append_jsonl(Path(__import__("pipeline.common.config", fromlist=["LEDGER"]).LEDGER) / "crawled.jsonl",
                 {"url": url, "final_url": final_url, "status": status, "note": note,
                  "ts": now_iso()})


def crawled_set():
    from . import config
    return load_key_set(config.LEDGER / "crawled.jsonl", "url")

