"""Search-engine adapters (Bing RSS / DuckDuckGo html / Sogou web) + generic
discovery driver with per-engine query ledgers, dedup, and health logging."""
import asyncio
import base64
import json
import re
from urllib.parse import parse_qs, quote_plus, urlparse

from bs4 import BeautifulSoup

from . import config, textutil
from .httpfetch import Fetcher
from .store import append_jsonl, load_jsonl, now_iso

CAPTCHA_HINTS = ("验证码", "captcha", "unusual traffic", "verify you are", "访问异常")


def normalize_url(url):
    """Strip fragments/utm, decode bing /ck/a redirect, lower host."""
    url = (url or "").strip()
    if not url.startswith("http"):
        return ""
    try:
        p = urlparse(url)
    except Exception:
        return ""
    host = p.netloc.lower()
    path = p.path
    # bing redirect wrapper /ck/a?...&u=a1<base64url>
    if host.endswith("bing.com") and path.startswith("/ck/"):
        qs = parse_qs(p.query)
        u = (qs.get("u") or [""])[0]
        if u.startswith("a1"):
            b64 = u[2:]
            b64 += "=" * (-len(b64) % 4)
            try:
                real = base64.urlsafe_b64decode(b64).decode("utf-8", "ignore")
                if real.startswith("http"):
                    return normalize_url(real)
            except Exception:
                pass
        return ""
    # drop tracking params
    keep = []
    for kv in p.query.split("&"):
        if not kv:
            continue
        k = kv.split("=")[0].lower()
        if k in ("utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content",
                 "spm", "from", "fr", "ns", "cl", "tn"):
            continue
        keep.append(kv)
    q = "&".join(keep)
    frag = ""
    out = f"{p.scheme}://{host}{path}" + (f"?{q}" if q else "") + frag
    if out.endswith("/"):
        out = out[:-1]
    return out


class Engine:
    name = "base"
    endpoint_host = ""

    def __init__(self, fetcher):
        self.f = fetcher
        self.consecutive_fail = 0

    async def search(self, query, n=15):
        raise NotImplementedError

    def note(self, results, err):
        if err or not results:
            self.consecutive_fail += 1
        else:
            self.consecutive_fail = 0
        return self.consecutive_fail >= 4


class BingRSS(Engine):
    name = "bing_rss"
    endpoint_host = "www.bing.com"

    async def search(self, query, n=15):
        url = (f"https://www.bing.com/search?q={quote_plus(query)}"
               f"&format=rss&count={min(n, 20)}&mkt=zh-CN&setlang=zh-hans")
        r = await self.f.fetch(url)
        if not r.ok:
            return [], f"http_{r.status_code or r.blocked}"
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(r.content)
            out = []
            for it in root.iter("item"):
                t = (it.findtext("title") or "").strip()
                l = (it.findtext("link") or "").strip()
                d = textutil.clean_ws(re.sub(r"<[^>]+>", "", it.findtext("description") or ""))
                if l.startswith("http"):
                    out.append({"title": t, "url": l, "snippet": d})
                if len(out) >= n:
                    break
            if not out:
                return [], "empty_results"
            return out, None
        except Exception as e:
            return [], f"parse:{e.__class__.__name__}"


class DDGHtml(Engine):
    name = "ddg"
    endpoint_host = "html.duckduckgo.com"

    async def search(self, query, n=15):
        url = f"https://html.duckduckgo.com/html/?q={quote_plus(query)}&kl=cn-zh"
        r = await self.f.fetch(url)
        if not r.ok:
            return [], f"http_{r.status_code or r.blocked}"
        soup = BeautifulSoup(textutil.dammit(r.content), "lxml")
        out = []
        for a in soup.select("a.result__a"):
            href = a.get("href", "")
            real = href
            if "uddg=" in href:
                try:
                    real = parse_qs(urlparse(href).query).get("uddg", [href])[0]
                except Exception:
                    pass
            real = normalize_url(real)
            if not real:
                continue
            rec = {"title": a.get_text(" ", strip=True), "url": real, "snippet": ""}
            node = a.find_parent("div", class_="result") or a.parent
            sn = node.select_one(".result__snippet") if node else None
            if sn:
                rec["snippet"] = textutil.clean_ws(sn.get_text(" ", strip=True))
            out.append(rec)
            if len(out) >= n:
                break
        if not out:
            body_snip = textutil.clean_ws(soup.get_text(" ", strip=True))[:120]
            if any(h in body_snip.lower() for h in CAPTCHA_HINTS):
                return [], "captcha"
            return [], "empty_results"
        return out, None


class Sogou(Engine):
    name = "sogou"
    endpoint_host = "www.sogou.com"

    async def search(self, query, n=15):
        url = f"https://www.sogou.com/web?query={quote_plus(query)}"
        r = await self.f.fetch(url)
        if not r.ok:
            return [], f"http_{r.status_code or r.blocked}"
        soup = BeautifulSoup(textutil.dammit(r.content), "lxml")
        out = []
        for h in soup.select("h3 a, h3.vr-title a, a.title-link"):
            href = h.get("href", "")
            if href.startswith("//"):
                href = "https:" + href
            elif href.startswith("/"):
                href = "https://www.sogou.com" + href
            if not href.startswith("http"):
                continue
            rec = {"title": h.get_text(" ", strip=True), "url": href, "snippet": ""}
            box = h.find_parent(["div", "section"])
            if box:
                sm = box.select_one(".str-text-info, .str_info, .space-txt, p.txt-info")
                if sm:
                    rec["snippet"] = textutil.clean_ws(sm.get_text(" ", strip=True))
            out.append(rec)
            if len(out) >= n:
                break
        body_snip = textutil.clean_ws(soup.get_text(" ", strip=True))[:200]
        if not out:
            if any(h in body_snip for h in CAPTCHA_HINTS) or "antispider" in body_snip.lower():
                return [], "captcha"
            return [], "empty_results"
        return out, None


ENGINES = {"bing_rss": BingRSS, "ddg": DDGHtml, "sogou": Sogou}


def queries_ledger(engine):
    return config.LEDGER / f"queries_{engine}.jsonl"


async def run_discovery(queries, out_path, engines=("bing_rss", "ddg", "sogou"),
                        per_query=14, max_queries=None, fetcher=None):
    """Run queries across engines; append leads to out_path; idempotent by query+engine."""
    own_fetcher = fetcher is None
    f = fetcher or Fetcher()
    seen_urls = {r.get("url") for r in load_jsonl(out_path) if r.get("url")}
    stats = {e: {"queries": 0, "results": 0, "errors": 0} for e in engines}
    done_q = {e: {r["query"] for r in load_jsonl(queries_ledger(e)) if r.get("query")}
              for e in engines}
    active = list(engines)
    try:
        for q in queries:
            if max_queries and sum(s["queries"] for s in stats.values()) >= max_queries:
                break
            for name in list(active):
                eng = ENGINES[name](f)
                if q in done_q[name]:
                    continue
                ledger_count = len(done_q[name])
                if ledger_count >= config.ENGINE_QUERY_CAP:
                    active.remove(name)
                    append_jsonl(config.LEDGER / "engine_health.jsonl",
                                 {"engine": name, "event": "query_cap_reached", "ts": now_iso()})
                    continue
                results, err = await eng.search(q, n=per_query)
                append_jsonl(queries_ledger(name),
                             {"query": q, "ts": now_iso(), "n": len(results), "err": err})
                stats[name]["queries"] += 1
                if err:
                    stats[name]["errors"] += 1
                    if eng.note(results, err):
                        active.remove(name)
                        append_jsonl(config.LEDGER / "engine_health.jsonl",
                                     {"engine": name, "event": "disabled_consecutive_fail",
                                      "ts": now_iso()})
                    await asyncio.sleep(2)
                    continue
                new = 0
                for rank, rec in enumerate(results, 1):
                    nu = normalize_url(rec["url"])
                    if not nu or nu in seen_urls:
                        continue
                    # skip the engine's own domain and pure query-pages
                    if urlparse(nu).netloc in (eng.endpoint_host, "www.baidu.com", "m.baidu.com"):
                        continue
                    seen_urls.add(nu)
                    append_jsonl(out_path, {"query": q, "engine": name, "rank": rank,
                                            "title": rec["title"][:200],
                                            "snippet": rec["snippet"][:400],
                                            "url": nu, "raw_url": rec["url"],
                                            "ts": now_iso()})
                    new += 1
                stats[name]["results"] += new
    finally:
        if own_fetcher:
            await f.aclose()
    return stats

