                                            "url": nu, "raw_url": rec["url"],
                                            "ts": now_iso()})
                    new += 1
                stats[name]["results"] += new
                qi += 1
                await asyncio.sleep(random.uniform(2.0, 4.0))
    finally:
        if own:
            await f.aclose()
    return stats

