        return None

    def _cache_put(self, url, res):
        if not res.ok:
            return
        k = self._key(url)
        (self.cache_dir / (k + ".body")).write_bytes(res.content)
        (self.cache_dir / (k + ".meta.json")).write_text(json.dumps({
            "url": url, "final_url": res.final_url, "status": res.status,
            "ts": time.time(), "ct": "n/a"}, ensure_ascii=False), encoding="utf-8")

    # ---------- robots ----------
    async def _robots_ok(self, url):
        if not self.respect_robots:
            return True
        p = urlparse(url)
        host = p.netloc
        if host in self._robots:
            parser, ok = self._robots[host]
        else:
            parser, ok = await self._load_robots(p)
            self._robots[host] = (parser, ok)
        if not ok:
            return False
        try:
            return parser.can_fetch("*", url)
        except Exception:
            return False

    async def _load_robots(self, parts):
        parser = robotparser.RobotFileParser()
        robots_url = f"{parts.scheme}://{parts.netloc}/robots.txt"
        for attempt in range(3):
            try:
                r = await self.client.get(robots_url, headers={"User-Agent": UAS[0]})
                if r.status_code == 200:
                    parser.parse(r.text.splitlines())
                    return parser, True
                if r.status_code == 404:
                    return parser, True  # no robots -> allowed
                if r.status_code in (401, 403):
                    return parser, False  # can't read robots -> conservative
                # 5xx / other: retry, then conservative
            except Exception:
                pass
            await asyncio.sleep(1.5 * (attempt + 1))
        return parser, False

    # ---------- main ----------
    def _domain_lock(self, host):
        if host not in self._dlock:
            self._dlock[host] = asyncio.Lock()
        return self._dlock[host]

    async def fetch(self, url, referer=None, force=False, max_bytes=15_000_000):
        if not force:
            cached = self._cache_get(url)
            if cached is not None:
                return cached
        parts = urlparse(url)
        host = parts.netloc
        if self._dhits.get(host, 0) >= self.max_per_domain:
            return FetchResult(url, blocked="domain_cap")
        if not await self._robots_ok(url):
            return FetchResult(url, blocked="robots_disallow")
        async with self._sem:
            lock = self._domain_lock(host)
            async with lock:
                wait = 0.0
                last = self._dlast.get(host)
                if last is not None:
                    wait = max(0.0, random.uniform(*self.delay) - (time.monotonic() - last))
                    if wait > 0:
                        await asyncio.sleep(wait)
                self._dhits[host] = self._dhits.get(host, 0) + 1
                self._dlast[host] = time.monotonic()
                return await self._fetch_once(url, referer)

    async def _fetch_once(self, url, referer=None):
        headers = {"User-Agent": random.choice(UAS)}
        if referer:
            headers["Referer"] = referer
        delay = 3.0
        last_err = None
        for attempt in range(self.max_retries):
            client = self.client
            try:
                r = await client.get(url, headers=headers)
                if r.status_code == 200:
                    res = FetchResult(url, str(r.url), 200, True, False, r.content[:15_000_000])
                    self._cache_put(url, res)
                    return res
                if r.status_code in (429, 500, 502, 503, 504):
                    last_err = f"http_{r.status_code}"
                    await asyncio.sleep(delay + random.uniform(0, 2))
                    delay *= 2
                    continue
                if r.status_code in (403, 401, 406):
                    return FetchResult(url, str(r.url), r.status_code, False, False,
                                       error="blocked_" + last_err.__class__.__name__ if last_err else "blocked")
                return FetchResult(url, str(r.url), r.status_code, False, False,
                                   error=f"http_{r.status_code}")
            except httpx.HTTPError as e:
                name = e.__class__.__name__
                if isinstance(e, httpx.ConnectError) and "SSLError" in str(e.__cause__ if e.__cause__ else ""):
                    client = self.client_nv
                last_err = name
                await asyncio.sleep(delay + random.uniform(0, 2))
                delay *= 2
                continue
            except Exception as e:
                last_err = f"{e.__class__.__name__}:{e}"[:120]
                await asyncio.sleep(delay)
                delay *= 2
                continue
        res = FetchResult(url, error=f"exhausted:{last_err}")
        if self.failure_log:
            try:
                self.failure_log(res.to_json())
            except Exception:
                pass
        return res

