    "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:125.0) Gecko/20100101 Firefox/125.0",
]


class FetchResult:
    def __init__(self, url, final_url=None, status=0, ok=False, from_cache=False,
                 content=b"", error=None, blocked=None):
        self.url = url
        self.final_url = final_url or url
        self.status = status
        self.ok = ok
        self.from_cache = from_cache
        self.content = content
        self.error = error
        self.blocked = blocked  # reason string when robots/cap blocked the fetch

    def to_json(self):
        return {"url": self.url, "final_url": self.final_url, "status": self.status,
                "ok": self.ok, "from_cache": self.from_cache, "error": self.error,
                "blocked": self.blocked}


