    def __init__(self, cache_dir=None, concurrency=None, delay=None, timeout=None,
                 max_retries=None, max_per_domain=None, respect_robots=True,
                 failure_log=None):
        self.cache_dir = Path(cache_dir or config.RAW)
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        self.conc = concurrency or config.CONCURRENCY
        self.delay = delay or (config.DELAY_MIN, config.DELAY_MAX)
        self.timeout = timeout or config.TIMEOUT
        self.max_retries = max_retries or config.MAX_RETRIES
        self.max_per_domain = max_per_domain or config.MAX_PER_DOMAIN
        self.respect_robots = respect_robots
        self.failure_log = failure_log  # optional callable(dict)
        self._sem = asyncio.Semaphore(self.conc)
        self._dlock = {}
        self._dlast = {}
        self._dhits = {}
        self._robots = {}
        self.client = httpx.AsyncClient(follow_redirects=True, timeout=self.timeout,
                                        headers={"Accept-Language": "zh-CN,zh;q=0.9,en;q=0.5"})
        self.client_nv = httpx.AsyncClient(follow_redirects=True, timeout=self.timeout, verify=False,
                                           headers={"Accept-Language": "zh-CN,zh;q=0.9,en;q=0.5"})

    async def aclose(self):
        await self.client.aclose()
        await self.client_nv.aclose()

    async def __aenter__(self):
        return self

    async def __aexit__(self, *a):
        await self.aclose()

    # ---------- cache ----------
    def _key(self, url):
        return hashlib.sha1(url.encode("utf-8")).hexdigest()

    def _cache_get(self, url):
        k = self._key(url)
        meta = self.cache_dir / (k + ".meta.json")
        body = self.cache_dir / (k + ".body")
        if meta.exists() and body.exists():
