        except Exception:
            pass

    # ---------- main ----------
    def _domain_lock(self, host):
        if host not in self._dlock:
            self._dlock[host] = asyncio.Lock()
        return self._dlock[host]

    async def fetch(self, url, referer=None, force=False, max_bytes=15_000_000):
        if not force:
            cached = self._cache_get(url)
            if cached is not None:
                return cached
        parts = urlparse(url)
        host = parts.netloc
        if self._dhits.get(host, 0) >= self.max_per_domain:
            return FetchResult(url, blocked="domain_cap")
        if not await self._robots_ok(url):
