segment page text into per-course entries using the icourse course-name
dictionary, classify, anonymize, compliance-filter. One entry = one
(course x category) cluster per page with extractive facts only."""
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from pipeline.common import config, textutil
from pipeline.common.store import load_jsonl, append_jsonl, now_iso, sha1
from pipeline.d2_campus import compliance

SCHOOL_ALIASES = re.compile(r"(中国科学技术大学|中国科大|中科大|USTC|ustc|科大)")

BLOCK_SPLIT_RE = re.compile(r"\n{2,}|(?:^|\n)[\-–—=*_]{3,}")

COURSE_RE_HINT = re.compile(r"[\u4e00-\u9fa5A-Za-z0-9（）()·]{2,24}")


def build_course_dictionary(courses_path=None):
    """course_name(lowercased) -> canonical display name (longest wins)."""
    courses_path = courses_path or config.D2 / "icourse_courses.jsonl"
    d = {}
    for row in load_jsonl(courses_path):
        name = (row.get("course_name") or "").strip()
        if 2 <= len(name) <= 30:
            key = name.lower()
            if key not in d or len(name) > len(d[key]):
                d[key] = name
    return d


def find_course_mentions(text, course_dict):
    """Return set of canonical course names mentioned in text (substring match)."""
    hits = set()
    tl = (text or "").lower()
    if len(tl) > 20000:
        tl = tl[:20000]
    for key, canon in course_dict.items():
        if len(key) >= 3 and key in tl:
            hits.add(canon)
    return hits


def page_is_on_topic(text, title=""):
    return bool(SCHOOL_ALIASES.search((title or "") + " " + (text or "")[:3000]))


def segment_blocks(text):
    blocks, cur = [], []
    for line in (text or "").split("\n"):
        line = line.strip()
        if not line:
            continue
        if BLOCK_SPLIT_RE.match(line):
            if cur:
                blocks.append("\n".join(cur))
                cur = []
            continue
        cur.append(line)
    if cur:
        blocks.append("\n".join(cur))
    return blocks


def extract_entries_from_page(page, course_dict):
    """Yield entries for one crawled page."""
    url = page["final_url"]
    title = page.get("title", "")
    text = page.get("text", "")
    if not page_is_on_topic(text, title):
        return []
    full_hits = find_course_mentions(title + "\n" + text[:6000], course_dict)
    entries = []
    if full_hits:
        # per-course clusters: block-level attribution
        per_course = {c: [] for c in full_hits}
        unassigned = []
        for b in segment_blocks(text):
            hits = find_course_mentions(b, course_dict)
            if hits:
                for c in hits:
                    per_course.setdefault(c, []).append(b)
            elif len(b) >= 40:
                unassigned.append(b)
        for course, blocks in per_course.items():
            body = "\n".join(blocks)[:3000]
            if len(body) < 30:
                continue
            rec = make_entry(url, title, course, body)
            if rec:
                entries.append(rec)
    else:
        # no course dictionary match: title-derived single entry if title looks course-ish
        m = re.search(r"([\u4e00-\u9fa5A-Za-z0-9（）()]{2,20}?(?:课|课程|实验|数学|物理|英语))", title)
        if m and len(text) > 200:
            rec = make_entry(url, title, m.group(1), text[:3000])
            if rec:
                entries.append(rec)
    return entries


def make_entry(url, title, course, body):
    anonymized = compliance.anonymize(body)
    kept, n_attack, n_subj = compliance.filter_sentences(anonymized)
    if not kept:
        return None
    category = compliance.classify(anonymized)
    summary = compliance.summarize(anonymized)
    facts = compliance.key_facts(anonymized)
    if not facts:
        facts = kept[:2]
    return {
        "school": "中国科学技术大学",
        "course": textutil.truncate_chars(textutil.clean_ws(course), 60),
        "category": category,
        "summary": summary,
        "key_facts": facts,
        "n_original_chars": len(body),
        "url": url,
        "title_hint": textutil.truncate_chars(title, 120),
        "source_platform": host_of(url),
        "captured_at": now_iso(),
        "compliance": {"attack_sent_dropped": n_attack,
                       "teacher_subjective_dropped": n_subj},
    }


def host_of(url):
    from urllib.parse import urlparse
    try:
        h = urlparse(url).netloc
        return h[4:] if h.startswith("www.") else h
    except Exception:
        return ""


def run(pages_path=None, courses_path=None, out_path=None):
    pages_path = pages_path or config.CORPUS / "d2_pages.jsonl"
    out_path = out_path or config.DATASET_CT / "campus_tips_search.jsonl"
    course_dict = build_course_dictionary(courses_path)
    pages = load_jsonl(pages_path)
    seen = set()
    n_out = 0
    if out_path.exists():
        out_path.unlink()
    for page in pages:
        for rec in extract_entries_from_page(page, course_dict):
            h = sha1(rec["url"] + "|" + rec["course"] + "|" + rec["category"])[:20]
            if h in seen:
                continue
            seen.add(h)
            if compliance.pii_scan(rec["summary"] + " ".join(rec["key_facts"])):
                continue
            append_jsonl(out_path, rec)
            n_out += 1
    print(f"[extract_tips] pages={len(pages)} course_dict={len(course_dict)} entries={n_out}")
    return {"pages": len(pages), "entries": n_out}


if __name__ == "__main__":
    run()

