"""Apply LLM-review verdicts to both datasets: drop/relabel, add llm_review
provenance, export rejected records to clearly-marked sidecar files."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from pipeline.common import config
from pipeline.common.store import load_jsonl


def write_rows(path, rows):
    p = Path(path)
    with p.open("w", encoding="utf-8") as f:
        for r in rows:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")


def apply_d1():
    rows = load_jsonl(config.DATASET_TP / "teacher_prompts.jsonl")
    vmap = {}
    for part in (1, 2):
        for v in load_jsonl(config.D1 / f"verdicts_{part}.jsonl"):
            vmap[v["id"]] = v
    kept, rejected, missing = [], [], 0
    for r in rows:
        v = vmap.get(r["id"])
        if v is None:
            missing += 1
            kept.append(r)
            continue
        r["llm_review"] = {"verdict": v.get("verdict"), "reason": (v.get("reason") or "")[:40]}
        if v.get("verdict") == "keep":
            if v.get("scenario"):
                r["grading_scenario"] = v["scenario"]
            if "subject" in v:
                r["subject_context"] = v.get("subject") or ""
            kept.append(r)
        else:
            rejected.append(r)
    kept.sort(key=lambda r: -r.get("score", 0))
    write_rows(config.DATASET_TP / "teacher_prompts.jsonl", kept)
    write_rows(config.DATASET_TP / "teacher_prompts.rejected.jsonl", rejected)
    print(f"[apply_d1] kept={len(kept)} rejected={len(rejected)} missing_verdict={missing}")
    return kept, rejected


def apply_d2_search():
    rows = load_jsonl(config.DATASET_CT / "campus_tips_search.jsonl")
    vmap = {v["key"]: v for v in load_jsonl(config.D2 / "verdicts_search.jsonl")}
    kept, rejected, missing = [], [], 0
    for r in rows:
        key = f"{r.get('url')}|{r.get('course')}|{r.get('category')}"
        v = vmap.get(key)
        if v is None:
            missing += 1
            kept.append(r)
            continue
        r["llm_review"] = {"verdict": v.get("verdict"), "reason": (v.get("reason") or "")[:40]}
        if v.get("verdict") == "keep":
            if v.get("category"):
                r["category"] = v["category"]
            if v.get("summary_fix"):
                r["summary"] = v["summary_fix"]
            kept.append(r)
        else:
            rejected.append(r)
    write_rows(config.DATASET_CT / "campus_tips_search.jsonl", kept)
    write_rows(config.DATASET_CT / "campus_tips_search.rejected.jsonl", rejected)
    print(f"[apply_d2_search] kept={len(kept)} rejected={len(rejected)} missing_verdict={missing}")
    return kept, rejected


if __name__ == "__main__":
    apply_d1()
    apply_d2_search()

